SELECT fn_cp_import_case('deonto-refus-d-enregistrer-une-plainte-constate', '{"slug": "deonto-refus-d-enregistrer-une-plainte-constate", "title": "Votre collègue décourage un plaignant devant vous", "theme_slug": "deontologie", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 15 heures. À l''accueil du commissariat, vous constatez que votre collègue décourage activement un plaignant qui souhaite déposer plainte, cette attitude se déroulant directement devant vous et constituant un manquement au droit de cet usager qui se manifeste en temps réel sous vos yeux plutôt qu''après coup. Cette configuration, où cette faute par abstention se produit devant le public que constitue ce plaignant, nécessite une intervention immédiate de votre part pour reprendre cet accueil et garantir le droit de cette personne à voir sa plainte enregistrée.\n\nCette situation, caractéristique des manquements par abstention qui privent un usager d''un droit fondamental sans nécessiter de geste actif de la part de l''agent fautif, impose une intervention directe qui rétablisse immédiatement ce droit compromis par ce découragement constaté.\n\nCette configuration nécessite de reprendre cet accueil et de garantir le droit de ce plaignant, cette double exigence restant essentielle pour corriger immédiatement cette faute par abstention qui se déroule actuellement devant vous.", "questions": [{"position": 1, "max_points": 5, "label": "Comment reprenez-vous cet accueil pour garantir le droit de ce plaignant ?", "hint": "Cette reprise doit intervenir rapidement, cette action restant nécessaire pour corriger immédiatement ce manquement au droit de cet usager qui se déroule actuellement devant vous.", "perfect": "J''interviens rapidement pour reprendre cet accueil, cette action restant nécessaire face à ce découragement constaté envers ce plaignant qui souhaite déposer plainte.\n\nJe reste factuelle et bienveillante envers ce plaignant, cette attitude restant appropriée pour restaurer sa confiance après ce découragement initial subi.\n\nJe procède à l''enregistrement de cette plainte selon les règles normales de procédure, cette action garantissant concrètement le droit de cet usager à cette démarche.\n\nJe reste attentive à ne pas commenter directement devant lui l''attitude de mon collègue, cette discrétion restant appropriée pour ne pas l''impliquer davantage dans cette situation.", "points": [{"position": 1, "label": "Intervenir rapidement pour reprendre cet accueil", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action face au découragement constaté.", "groups": [{"position": 1, "keywords": ["accueil repris", "découragement constaté", "action rapide"]}]}, {"position": 2, "label": "Rester factuelle et bienveillante pour restaurer sa confiance", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Confiance restaurée après le découragement initial.", "groups": [{"position": 1, "keywords": ["confiance restaurée", "bienveillance appliquée", "découragement initial"]}]}, {"position": 3, "label": "Procéder à l''enregistrement de cette plainte selon les règles normales", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Droit garanti concrètement.", "groups": [{"position": 1, "keywords": ["plainte enregistrée", "règles normales", "droit garanti"]}]}, {"position": 4, "label": "Ne pas commenter directement l''attitude du collègue devant lui", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Discrétion évitant de l''impliquer davantage.", "groups": [{"position": 1, "keywords": ["discrétion maintenue", "commentaire évité", "implication limitée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous ce plaignant qui vient de subir ce découragement initial ?", "hint": "Ce plaignant mérite une attention particulière compte tenu de ce découragement qu''il vient de subir, cette gestion devant permettre de restaurer sa confiance envers cette démarche.", "perfect": "Je reste attentive à l''état de ce plaignant après ce découragement subi, cette vigilance restant nécessaire pour évaluer l''impact de cette situation sur sa démarche.\n\nJe reste factuelle et rassurante sur la suite de son accueil, cette communication restant appropriée pour apaiser les craintes que ce découragement a pu créer.\n\nJe reste attentive à recueillir sa plainte avec le sérieux et l''attention qu''elle mérite, cette rigueur restant essentielle après cet incident initial.\n\nJe reste disponible pour répondre à ses éventuelles questions sur la suite de cette procédure, cette disponibilité restant appropriée pour restaurer pleinement sa confiance.", "points": [{"position": 1, "label": "Rester attentive à l''état de ce plaignant après ce découragement subi", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vigilance sur l''impact de cette situation.", "groups": [{"position": 1, "keywords": ["état surveillé", "impact évalué", "découragement subi"]}]}, {"position": 2, "label": "Rester factuelle et rassurante sur la suite de son accueil", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Craintes apaisées par cette communication.", "groups": [{"position": 1, "keywords": ["craintes apaisées", "communication rassurante", "accueil poursuivi"]}]}, {"position": 3, "label": "Recueillir sa plainte avec le sérieux qu''elle mérite", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rigueur essentielle après cet incident.", "groups": [{"position": 1, "keywords": ["plainte recueillie", "sérieux appliqué", "incident dépassé"]}]}, {"position": 4, "label": "Rester disponible pour répondre à ses questions sur la suite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Confiance pleinement restaurée.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "questions accueillies", "confiance restaurée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de ce manquement de votre collègue constaté devant ce public ?", "hint": "Ce compte rendu doit refléter la gravité de ce manquement par abstention, cette transmission restant nécessaire malgré la relation de collègue qui vous lie à l''auteur de ce comportement.", "perfect": "Je transmets à ma hiérarchie ce manquement de mon collègue envers ce plaignant, cette information restant nécessaire malgré notre relation professionnelle habituelle.\n\nJe reste factuelle sur les circonstances précises de ce découragement observé, cette rigueur restant essentielle pour un compte rendu fidèle de cette situation.\n\nJe reste attentive à qualifier correctement cette faute par abstention plutôt que de la présenter comme un simple malentendu ou une négligence mineure.\n\nJe reste disponible pour toute précision complémentaire, cette réactivité restant utile pour permettre un traitement approprié de ce manquement constaté chez ce collègue.", "points": [{"position": 1, "label": "Transmettre ce manquement à la hiérarchie malgré la relation professionnelle", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information nécessaire indépendamment de la relation.", "groups": [{"position": 1, "keywords": ["manquement transmis", "relation professionnelle", "hiérarchie informée"]}]}, {"position": 2, "label": "Rester factuelle sur les circonstances précises de ce découragement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur pour un compte rendu fidèle.", "groups": [{"position": 1, "keywords": ["circonstances précisées", "compte rendu fidèle", "découragement observé"]}]}, {"position": 3, "label": "Qualifier correctement cette faute par abstention", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Distinction d''un simple malentendu ou négligence mineure.", "groups": [{"position": 1, "keywords": ["faute qualifiée", "malentendu écarté", "abstention identifiée"]}]}, {"position": 4, "label": "Rester disponible pour toute précision complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour un traitement approprié.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "traitement approprié", "précision complémentaire"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-utilisation-vehicule-service-personnel', '{"slug": "deonto-utilisation-vehicule-service-personnel", "title": "Un crochet par la pharmacie pendant la patrouille", "theme_slug": "deontologie", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 14 heures. Durant votre patrouille, votre équipier propose de faire un crochet par une pharmacie pour son propre compte personnel, ce détour restant en apparence mineur et de courte durée mais constituant néanmoins un cumul de plusieurs principes en jeu, notamment l''usage détourné du véhicule de service et le temps de service consacré à une démarche strictement personnelle. Cette configuration, où ce détour reste effectivement bref dans sa durée mais où l''accumulation de ces petits écarts pourrait progressivement banaliser un usage inapproprié des moyens du service, nécessite d''identifier clairement cet usage détourné même si son ampleur reste minime dans l''immédiat.\n\nCette situation, caractéristique des écarts mineurs qui peuvent progressivement s''installer dans les habitudes professionnelles sans jamais faire l''objet d''une remise en question explicite, impose de nommer ce détournement même minime plutôt que de le laisser passer sous prétexte de sa faible ampleur apparente.\n\nCette configuration nécessite d''identifier cet usage détourné même minime, cette exigence restant essentielle pour ne pas banaliser progressivement ce type de pratique au sein de votre patrouille quotidienne.", "questions": [{"position": 1, "max_points": 5, "label": "Comment identifiez-vous cet usage détourné du véhicule et du temps de service malgré son caractère minime ?", "hint": "Cette identification doit rester claire malgré l''apparence anodine de ce détour, cette exigence restant essentielle pour ne pas banaliser ce type d''écart au sein de votre patrouille.", "perfect": "J''identifie clairement cet usage détourné du véhicule de service pour cette démarche personnelle, cette qualification restant nécessaire malgré son ampleur apparemment minime.\n\nJe reste attentive au cumul des principes en jeu, notamment l''usage du véhicule et le temps de service consacrés à cette démarche personnelle de mon équipier.\n\nJe reste factuelle avec lui sur cette observation, cette clarté restant appropriée pour qu''il prenne conscience de la nature réelle de cette demande.\n\nJe reste attentive à ne pas laisser cet écart s''installer comme une habitude au sein de notre patrouille commune, cette vigilance restant essentielle pour l''avenir.", "points": [{"position": 1, "label": "Identifier clairement cet usage détourné malgré son ampleur minime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : qualification nécessaire malgré l''apparence anodine.", "groups": [{"position": 1, "keywords": ["usage détourné identifié", "ampleur minime", "qualification nécessaire"]}]}, {"position": 2, "label": "Rester attentive au cumul des principes en jeu dans cette demande", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Véhicule et temps de service cumulés.", "groups": [{"position": 1, "keywords": ["principes cumulés", "véhicule concerné", "temps de service"]}]}, {"position": 3, "label": "Rester factuelle avec lui sur cette observation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Clarté sur la nature réelle de cette demande.", "groups": [{"position": 1, "keywords": ["observation factuelle", "nature clarifiée", "demande précisée"]}]}, {"position": 4, "label": "Ne pas laisser cet écart s''installer comme une habitude", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance pour l''avenir de la patrouille.", "groups": [{"position": 1, "keywords": ["habitude évitée", "vigilance future", "patrouille commune"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment refusez-vous ce détour tout en préservant la relation avec votre équipier ?", "hint": "Ce refus doit rester ferme sur le principe tout en restant cordial dans la forme, cette conciliation restant appropriée pour préserver la relation de travail avec cet équipier.", "perfect": "Je refuse clairement ce détour proposé, cette fermeté restant nécessaire compte tenu de cet usage détourné du véhicule et du temps de service en jeu.\n\nJe reste factuelle sur les raisons de ce refus, expliquant que ce véhicule et ce temps de service ne peuvent être consacrés à cette démarche personnelle.\n\nJe reste cordiale dans la forme de ce refus, cette approche restant appropriée pour ne pas dégrader inutilement ma relation de travail avec cet équipier.\n\nJe reste attentive à proposer si possible une alternative appropriée, par exemple un passage personnel en dehors de ce temps et de ce véhicule de service.", "points": [{"position": 1, "label": "Refuser clairement ce détour proposé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : fermeté compte tenu de l''usage détourné.", "groups": [{"position": 1, "keywords": ["détour refusé", "usage détourné", "fermeté nécessaire"]}]}, {"position": 2, "label": "Expliquer factuellement les raisons de ce refus", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Véhicule et temps non consacrés à une démarche personnelle.", "groups": [{"position": 1, "keywords": ["raisons expliquées", "véhicule concerné", "démarche personnelle"]}]}, {"position": 3, "label": "Rester cordiale dans la forme de ce refus", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Relation de travail préservée.", "groups": [{"position": 1, "keywords": ["cordialité maintenue", "relation préservée", "forme appropriée"]}]}, {"position": 4, "label": "Proposer si possible une alternative appropriée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Passage personnel hors temps et véhicule de service.", "groups": [{"position": 1, "keywords": ["alternative proposée", "passage personnel", "temps distinct"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous la suite de cette patrouille après ce refus opposé à votre équipier ?", "hint": "Cette suite doit rester professionnelle malgré ce refus, cette continuité restant nécessaire pour assurer normalement la poursuite de cette patrouille commune.", "perfect": "Je reste attentive à poursuivre normalement cette patrouille malgré ce refus opposé, cette continuité restant nécessaire pour notre mission commune.\n\nJe reste factuelle et professionnelle dans mes échanges ultérieurs avec cet équipier, cette attitude restant appropriée pour ne pas prolonger inutilement cette tension ponctuelle.\n\nJe reste attentive à ne pas dramatiser cet incident mineur au-delà de ce qu''il représente réellement, cette mesure restant appropriée pour préserver un cadre de travail fonctionnel.\n\nJe reste vigilante face à d''éventuelles demandes similaires qui pourraient survenir à l''avenir durant nos patrouilles communes.", "points": [{"position": 1, "label": "Poursuivre normalement cette patrouille malgré ce refus opposé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : continuité pour la mission commune.", "groups": [{"position": 1, "keywords": ["patrouille poursuivie", "mission commune", "continuité assurée"]}]}, {"position": 2, "label": "Rester factuelle et professionnelle dans les échanges ultérieurs", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Tension ponctuelle non prolongée.", "groups": [{"position": 1, "keywords": ["échanges professionnels", "tension ponctuelle", "attitude appropriée"]}]}, {"position": 3, "label": "Ne pas dramatiser cet incident mineur au-delà de sa réalité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Mesure préservant un cadre de travail fonctionnel.", "groups": [{"position": 1, "keywords": ["dramatisation évitée", "mesure appliquée", "cadre fonctionnel"]}]}, {"position": 4, "label": "Rester vigilante face à d''éventuelles demandes similaires futures", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance pour les patrouilles communes futures.", "groups": [{"position": 1, "keywords": ["vigilance maintenue", "demandes futures", "patrouilles communes"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-propos-envers-une-personne-interpellee', '{"slug": "deonto-propos-envers-une-personne-interpellee", "title": "Les remarques continuent pendant tout le trajet", "theme_slug": "deontologie", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 23 heures. Dans le véhicule de service transportant une personne interpellée, votre collègue tient des remarques humiliantes qui continuent pendant tout le trajet vers le commissariat, cette personne restant captive de cette situation sans possibilité de s''y soustraire, ce huis clos du véhicule créant une configuration où cette atteinte à la dignité s''exerce sans violence physique mais de manière prolongée et sans témoin extérieur. Cette configuration, où cette absence de témoin extérieur à ce véhicule pourrait laisser penser que cette situation reste sans conséquence, nécessite de faire cesser ces remarques et de les signaler malgré cette absence de tout témoin extérieur au véhicule.\n\nCette situation, caractéristique des atteintes à la dignité qui se déroulent dans un cadre confiné où la personne visée reste captive et sans échappatoire face à ces propos humiliants, impose une intervention rapide qui fasse cesser ce comportement avant qu''il ne se prolonge davantage durant ce trajet.\n\nCette configuration nécessite de faire cesser ces remarques et de les signaler malgré l''absence de témoin extérieur, cette double exigence restant essentielle pour protéger cette personne captive de cette situation dégradante.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous cesser ces remarques de votre collègue envers cette personne captive de ce trajet ?", "hint": "Cette interruption doit intervenir rapidement, cette action restant nécessaire pour protéger cette personne qui reste captive de cette situation sans possibilité de s''y soustraire.", "perfect": "J''interviens fermement pour faire cesser ces remarques de mon collègue, cette action restant nécessaire face à cette situation d''humiliation prolongée constatée.\n\nJe reste factuelle dans mon intervention, rappelant à ce collègue le caractère inapproprié de ces propos envers cette personne qui reste captive de ce trajet.\n\nJe reste attentive à l''état de cette personne interpellée durant ce trajet, cette vigilance restant nécessaire compte tenu de cette situation d''humiliation qu''elle subit.\n\nJe reste ferme malgré l''absence de tout témoin extérieur à ce véhicule, cette fermeté ne devant pas varier selon la présence ou l''absence de regard extérieur.", "points": [{"position": 1, "label": "Intervenir fermement pour faire cesser ces remarques", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action face à cette humiliation prolongée.", "groups": [{"position": 1, "keywords": ["remarques cessées", "humiliation prolongée", "action ferme"]}]}, {"position": 2, "label": "Rappeler factuellement le caractère inapproprié de ces propos", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Personne captive de ce trajet.", "groups": [{"position": 1, "keywords": ["propos inappropriés", "personne captive", "rappel factuel"]}]}, {"position": 3, "label": "Rester attentive à l''état de cette personne durant ce trajet", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance compte tenu de l''humiliation subie.", "groups": [{"position": 1, "keywords": ["état surveillé", "humiliation subie", "vigilance maintenue"]}]}, {"position": 4, "label": "Rester ferme malgré l''absence de tout témoin extérieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Fermeté ne variant pas selon le regard extérieur.", "groups": [{"position": 1, "keywords": ["fermeté constante", "témoin absent", "regard extérieur"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous cette personne interpellée durant la suite de ce trajet vers le commissariat ?", "hint": "Cette personne mérite une attention particulière compte tenu de cette humiliation subie, cette gestion devant permettre de rétablir un cadre respectueux pour la suite de ce trajet.", "perfect": "Je reste attentive à traiter cette personne avec le respect dû à toute personne interpellée, cette attitude restant essentielle malgré les faits qui motivent cette interpellation.\n\nJe reste factuelle et posée dans mes échanges avec elle durant la suite de ce trajet, cette approche restant appropriée pour compenser cette humiliation initiale subie.\n\nJe reste attentive à ne pas minimiser ce qu''elle vient de subir, cette reconnaissance restant appropriée pour restaurer une part de dignité durant ce trajet.\n\nJe reste attentive à l''informer, si pertinent, de la possibilité de signaler ces propos une fois arrivée au commissariat.", "points": [{"position": 1, "label": "Traiter cette personne avec le respect dû malgré les faits motivant l''interpellation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : respect indépendant des faits reprochés.", "groups": [{"position": 1, "keywords": ["respect maintenu", "faits motivant l''interpellation", "attitude essentielle"]}]}, {"position": 2, "label": "Rester factuelle et posée pour compenser cette humiliation initiale", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Approche appropriée durant la suite du trajet.", "groups": [{"position": 1, "keywords": ["attitude posée", "humiliation compensée", "trajet poursuivi"]}]}, {"position": 3, "label": "Ne pas minimiser ce qu''elle vient de subir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance restaurant une part de dignité.", "groups": [{"position": 1, "keywords": ["subi reconnu", "dignité restaurée", "minimisation évitée"]}]}, {"position": 4, "label": "L''informer de la possibilité de signaler ces propos au commissariat", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information utile si pertinente.", "groups": [{"position": 1, "keywords": ["signalement possible", "information donnée", "commissariat rejoint"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment signalez-vous ces propos malgré l''absence de tout témoin extérieur à ce véhicule ?", "hint": "Ce signalement doit intervenir malgré cette absence de témoin, cette transmission restant nécessaire pour documenter cette atteinte à la dignité constatée durant ce trajet en huis clos.", "perfect": "Je signale ces propos à ma hiérarchie une fois ce trajet terminé, cette transmission restant nécessaire malgré l''absence de tout témoin extérieur à ce véhicule.\n\nJe reste factuelle sur le contenu exact de ces remarques et leur caractère prolongé durant l''ensemble de ce trajet vers le commissariat.\n\nJe reste attentive à ne pas minimiser la gravité de cette situation sous prétexte de cette absence de témoin extérieur qui rendrait cette preuve plus difficile.\n\nJe reste disponible pour toute précision complémentaire, cette réactivité restant utile pour permettre un traitement approprié de ce manquement constaté.", "points": [{"position": 1, "label": "Signaler ces propos à la hiérarchie malgré l''absence de témoin extérieur", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : transmission nécessaire malgré le huis clos.", "groups": [{"position": 1, "keywords": ["propos signalés", "témoin absent", "hiérarchie informée"]}]}, {"position": 2, "label": "Rester factuelle sur le contenu et le caractère prolongé de ces remarques", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Description précise du trajet concerné.", "groups": [{"position": 1, "keywords": ["contenu précisé", "caractère prolongé", "trajet décrit"]}]}, {"position": 3, "label": "Ne pas minimiser la gravité sous prétexte de cette absence de témoin", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Gravité maintenue malgré la difficulté probatoire.", "groups": [{"position": 1, "keywords": ["gravité maintenue", "preuve difficile", "minimisation évitée"]}]}, {"position": 4, "label": "Rester disponible pour toute précision complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour un traitement approprié.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "traitement approprié", "précision complémentaire"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-information-donnee-a-un-avocat-hors-cadre', '{"slug": "deonto-information-donnee-a-un-avocat-hors-cadre", "title": "Il insiste courtoisement pour connaître l''avancement du dossier", "theme_slug": "deontologie", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 17 heures. Au commissariat, un avocat se présente et insiste courtoisement pour connaître l''avancement d''un dossier qui ne relève pas de la procédure normale d''accès à l''information dont il pourrait légitimement disposer, cette insistance restant polie et professionnelle mais constituant néanmoins une demande qui sort du cadre approprié pour ce type de sollicitation. Cette configuration, où cet interlocuteur reste légitime dans sa qualité de professionnel du droit mais où sa demande dépasse le cadre normal d''accès à cette information, nécessite de le renvoyer vers le cadre approprié sans pour autant faire preuve de discourtoisie envers ce professionnel.\n\nCette situation, caractéristique des sollicitations par des professionnels du droit qui, tout en restant légitimes dans leur qualité, formulent des demandes qui sortent du cadre normal de transmission de ce type d''information, impose une gestion qui concilie fermeté sur le fond et courtoisie dans la forme.\n\nCette configuration nécessite de renvoyer cet avocat vers le cadre approprié sans discourtoisie, cette double exigence restant essentielle pour gérer cette sollicitation qui reste légitime dans son principe mais inappropriée dans ses modalités actuelles.", "questions": [{"position": 1, "max_points": 5, "label": "Comment renvoyez-vous cet avocat vers le cadre approprié pour cette demande d''information ?", "hint": "Ce renvoi doit rester clair sur le fond tout en restant courtois dans la forme, cette conciliation restant nécessaire pour gérer cette sollicitation qui sort du cadre normal.", "perfect": "Je reste factuelle sur le fait que cette information ne peut lui être communiquée dans ce cadre, cette précision restant nécessaire face à cette demande hors procédure.\n\nJe l''oriente vers les voies appropriées d''accès à cette information, notamment les démarches procédurales normales qui s''appliquent à sa qualité d''avocat.\n\nJe reste attentive à ne pas céder à cette insistance malgré son caractère courtois, cette fermeté restant essentielle sur le fond de cette demande.\n\nJe reste factuelle sur les raisons de ce renvoi vers ce cadre approprié, cette explication restant utile pour qu''il comprenne cette limite malgré sa qualité professionnelle.", "points": [{"position": 1, "label": "Rester factuelle sur l''impossibilité de communiquer cette information", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : précision face à cette demande hors procédure.", "groups": [{"position": 1, "keywords": ["information non communiquée", "demande hors procédure", "précision apportée"]}]}, {"position": 2, "label": "Orienter vers les voies appropriées d''accès à cette information", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Démarches procédurales normales pour sa qualité.", "groups": [{"position": 1, "keywords": ["voies appropriées", "démarches procédurales", "qualité d''avocat"]}]}, {"position": 3, "label": "Ne pas céder à cette insistance malgré son caractère courtois", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Fermeté essentielle sur le fond.", "groups": [{"position": 1, "keywords": ["insistance résistée", "fermeté maintenue", "fond de la demande"]}]}, {"position": 4, "label": "Expliquer les raisons de ce renvoi vers le cadre approprié", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Compréhension de cette limite malgré la qualité professionnelle.", "groups": [{"position": 1, "keywords": ["raisons expliquées", "limite comprise", "qualité professionnelle"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment restez-vous courtoise envers cet avocat malgré ce refus nécessaire ?", "hint": "Cette courtoisie doit rester constante malgré ce refus sur le fond, cette conciliation restant nécessaire pour préserver une relation professionnelle appropriée avec cet interlocuteur légitime.", "perfect": "Je reste courtoise et respectueuse envers cet avocat tout au long de cet échange, cette attitude restant appropriée malgré ce refus nécessaire sur le fond de sa demande.\n\nJe reste attentive à reconnaître la légitimité de sa qualité professionnelle, cette reconnaissance restant compatible avec la fermeté nécessaire sur cette demande précise.\n\nJe reste factuelle et posée dans mes explications, cette approche restant appropriée pour éviter toute impression de rejet personnel de sa part.\n\nJe reste disponible pour orienter utilement sa démarche vers le cadre approprié, cette disponibilité restant appréciable malgré ce refus initial de sa demande.", "points": [{"position": 1, "label": "Rester courtoise et respectueuse tout au long de cet échange", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : attitude appropriée malgré le refus sur le fond.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "refus nécessaire", "échange respectueux"]}]}, {"position": 2, "label": "Reconnaître la légitimité de sa qualité professionnelle", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance compatible avec la fermeté nécessaire.", "groups": [{"position": 1, "keywords": ["qualité reconnue", "fermeté compatible", "demande précise"]}]}, {"position": 3, "label": "Rester factuelle et posée pour éviter une impression de rejet personnel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Approche appropriée dans les explications.", "groups": [{"position": 1, "keywords": ["explications posées", "rejet personnel évité", "approche appropriée"]}]}, {"position": 4, "label": "Rester disponible pour orienter utilement cette démarche", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilité appréciable malgré le refus initial.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "démarche orientée", "refus initial"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous une éventuelle insistance persistante de cet avocat sur cette demande ?", "hint": "Cette insistance persistante doit être gérée avec la même fermeté constante, cette continuité restant nécessaire face à une demande qui reste inappropriée quelle que soit la persistance de cette sollicitation.", "perfect": "Je reste ferme et constante dans mon refus si cet avocat persiste dans cette demande, cette continuité restant nécessaire malgré cette insistance renouvelée.\n\nJe reste factuelle sur le caractère définitif de ce refus dans ce cadre précis, cette clarté restant appropriée pour éviter toute ambiguïté sur ma position.\n\nJe reste attentive à orienter cette insistance vers ma hiérarchie si cela s''avérait nécessaire, cette transmission restant appropriée en cas de blocage persistant.\n\nJe reste professionnelle malgré cette insistance persistante, cette maîtrise restant essentielle pour ne pas transformer cette situation en confrontation inutile.", "points": [{"position": 1, "label": "Rester ferme et constante si cet avocat persiste dans cette demande", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : continuité malgré cette insistance renouvelée.", "groups": [{"position": 1, "keywords": ["fermeté constante", "insistance renouvelée", "continuité maintenue"]}]}, {"position": 2, "label": "Rester factuelle sur le caractère définitif de ce refus", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarté évitant toute ambiguïté.", "groups": [{"position": 1, "keywords": ["refus définitif", "ambiguïté évitée", "position claire"]}]}, {"position": 3, "label": "Orienter cette insistance vers la hiérarchie si nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transmission appropriée en cas de blocage.", "groups": [{"position": 1, "keywords": ["hiérarchie sollicitée", "blocage persistant", "transmission appropriée"]}]}, {"position": 4, "label": "Rester professionnelle sans transformer cela en confrontation inutile", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Maîtrise évitant une confrontation inutile.", "groups": [{"position": 1, "keywords": ["professionnalisme maintenu", "confrontation évitée", "maîtrise appliquée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('deonto-collegue-en-difficulte-personnelle-manquements', '{"slug": "deonto-collegue-en-difficulte-personnelle-manquements", "title": "Ses oublis se multiplient depuis sa séparation", "theme_slug": "deontologie", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 12 heures. Au service, vous constatez que les oublis de votre collègue se multiplient depuis sa séparation récente, ces manquements répétés dans l''exécution de ses tâches professionnelles traduisant manifestement une souffrance personnelle qui affecte désormais la qualité de son travail et potentiellement la sécurité du service dans son ensemble. Cette configuration, où cette solidarité humaine envers ce collègue en difficulté entre en tension avec la nécessité de signaler des manquements qui pourraient présenter un risque pour la sécurité collective, nécessite de concilier ces deux exigences apparemment contradictoires.\n\nCette situation, caractéristique des manquements professionnels qui trouvent leur origine dans une souffrance personnelle traversée par un collègue, impose une gestion qui ne sacrifie ni le soutien humain nécessaire ni la vigilance sur les risques que ces manquements pourraient représenter.\n\nCette configuration nécessite de concilier le soutien à ce collègue et le signalement du risque que représentent ces manquements, cette double exigence restant essentielle pour une gestion humaine et responsable de cette situation.", "questions": [{"position": 1, "max_points": 5, "label": "Comment apportez-vous un soutien à ce collègue traversant cette période difficile ?", "hint": "Ce soutien doit rester sincère et approprié, cette solidarité humaine restant essentielle face à cette souffrance personnelle que ce collègue traverse actuellement.", "perfect": "Je reste à l''écoute de ce collègue sur les difficultés qu''il traverse depuis cette séparation, cette écoute restant importante pour lui témoigner ma solidarité.\n\nJe reste attentive à ne pas le juger sur ces manquements qui trouvent leur origine dans cette souffrance personnelle qu''il traverse actuellement.\n\nJe reste disponible pour l''orienter vers des ressources de soutien appropriées, notamment psychologiques, si cela pouvait l''aider à traverser cette période.\n\nJe reste attentive à maintenir une relation de confiance avec lui malgré la nécessité parallèle de signaler certains de ces manquements.", "points": [{"position": 1, "label": "Rester à l''écoute de ce collègue sur ses difficultés", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : écoute témoignant la solidarité.", "groups": [{"position": 1, "keywords": ["écoute apportée", "difficultés partagées", "solidarité témoignée"]}]}, {"position": 2, "label": "Ne pas le juger sur ces manquements liés à sa souffrance", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Origine de ces manquements reconnue.", "groups": [{"position": 1, "keywords": ["jugement évité", "souffrance reconnue", "origine identifiée"]}]}, {"position": 3, "label": "Rester disponible pour l''orienter vers des ressources de soutien", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ressources psychologiques appropriées.", "groups": [{"position": 1, "keywords": ["ressources proposées", "soutien psychologique", "orientation offerte"]}]}, {"position": 4, "label": "Maintenir une relation de confiance malgré la nécessité de signalement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Confiance préservée en parallèle du signalement.", "groups": [{"position": 1, "keywords": ["confiance maintenue", "relation préservée", "signalement parallèle"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment signalez-vous le risque que ces manquements répétés représentent pour la sécurité du service ?", "hint": "Ce signalement doit intervenir malgré la solidarité que vous témoignez à ce collègue, cette transmission restant nécessaire compte tenu du risque réel que ces manquements pourraient représenter.", "perfect": "Je signale ces manquements répétés à ma hiérarchie, cette transmission restant nécessaire compte tenu du risque réel qu''ils pourraient représenter pour la sécurité du service.\n\nJe reste factuelle sur la nature et la fréquence de ces oublis constatés, cette précision restant utile pour une appréciation appropriée de cette situation.\n\nJe reste attentive à présenter cette situation avec nuance, expliquant le contexte personnel difficile qui explique ces manquements sans pour autant les excuser totalement.\n\nJe reste attentive à ce que ce signalement puisse aussi déboucher sur un accompagnement de ce collègue plutôt que sur une seule sanction disciplinaire.", "points": [{"position": 1, "label": "Signaler ces manquements répétés à la hiérarchie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : transmission nécessaire compte tenu du risque.", "groups": [{"position": 1, "keywords": ["manquements signalés", "risque reconnu", "hiérarchie informée"]}]}, {"position": 2, "label": "Rester factuelle sur la nature et la fréquence de ces oublis", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision pour une appréciation appropriée.", "groups": [{"position": 1, "keywords": ["nature précisée", "fréquence constatée", "appréciation appropriée"]}]}, {"position": 3, "label": "Présenter cette situation avec nuance en expliquant le contexte personnel", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contexte expliqué sans excuse totale.", "groups": [{"position": 1, "keywords": ["contexte expliqué", "nuance appliquée", "excuse partielle"]}]}, {"position": 4, "label": "Rechercher un accompagnement plutôt qu''une seule sanction disciplinaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Accompagnement recherché pour ce collègue.", "groups": [{"position": 1, "keywords": ["accompagnement recherché", "sanction évitée", "collègue soutenu"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous la relation avec ce collègue une fois ce signalement effectué ?", "hint": "Cette relation doit rester préservée malgré ce signalement nécessaire, cette continuité restant importante pour que ce collègue ne se sente pas trahi par cette démarche entreprise dans son intérêt.", "perfect": "Je reste transparente avec ce collègue sur ce signalement effectué, cette honnêteté restant appropriée pour qu''il comprenne les raisons de cette démarche.\n\nJe reste attentive à lui expliquer que ce signalement vise avant tout sa protection et celle du service plutôt qu''une volonté de lui nuire.\n\nJe reste disponible pour continuer à le soutenir humainement malgré ce signalement effectué, cette continuité restant importante pour préserver notre relation.\n\nJe reste attentive à l''évolution de sa situation après ce signalement, cette vigilance restant utile pour ajuster mon soutien selon les suites données à cette transmission.", "points": [{"position": 1, "label": "Rester transparente avec ce collègue sur ce signalement effectué", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : honnêteté sur les raisons de cette démarche.", "groups": [{"position": 1, "keywords": ["transparence maintenue", "signalement expliqué", "raisons comprises"]}]}, {"position": 2, "label": "Expliquer que ce signalement vise sa protection et celle du service", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Protection plutôt que volonté de nuire.", "groups": [{"position": 1, "keywords": ["protection visée", "volonté de nuire écartée", "service protégé"]}]}, {"position": 3, "label": "Rester disponible pour continuer à le soutenir humainement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Continuité préservant la relation.", "groups": [{"position": 1, "keywords": ["soutien maintenu", "relation préservée", "continuité assurée"]}]}, {"position": 4, "label": "Rester attentive à l''évolution de sa situation après ce signalement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance ajustant le soutien apporté.", "groups": [{"position": 1, "keywords": ["évolution suivie", "soutien ajusté", "suites données"]}]}]}]}'::jsonb);